import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "../styles/articles.css";

function ArticlesPage() {
  const { category } = useParams();
  const [articles, setArticles] = useState([]);
  const [isAdmin, setIsAdmin] = useState(false);
  const [expandedArticleId, setExpandedArticleId] = useState(null);
  const [comments, setComments] = useState({});
  const [newComments, setNewComments] = useState({});
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  // --- Отримання користувача ---
  useEffect(() => {
    const fetchUser = async () => {
      if (!token) return;
      try {
        const res = await fetch("http://127.0.0.1:8000/api/user/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await res.json();
        setIsAdmin(data.is_staff || data.is_superuser);
      } catch (err) {
        console.error("Помилка при отриманні користувача:", err);
      }
    };
    fetchUser();
  }, [token]);

  // --- Завантаження статей ---
  useEffect(() => {
    const fetchArticles = async () => {
      try {
        const res = await fetch(`http://127.0.0.1:8000/api/articles/?category=${category}`, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        });
        const data = await res.json();
        setArticles(data);
      } catch (err) {
        console.error("Помилка при завантаженні статей:", err);
      }
    };
    fetchArticles();
  }, [category, token]);

  // --- Завантаження коментарів ---
  const fetchComments = async (articleId) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/comments/?article=${articleId}`);
      const data = await res.json();
      setComments((prev) => ({ ...prev, [articleId]: data }));
    } catch (err) {
      console.error("Помилка при завантаженні коментарів:", err);
    }
  };

  const handleToggleComments = (articleId) => {
    if (expandedArticleId === articleId) {
      setExpandedArticleId(null);
    } else {
      setExpandedArticleId(articleId);
      if (!comments[articleId]) fetchComments(articleId);
    }
  };

  // --- Додати коментар ---
  const handleAddComment = async (articleId, content) => {
    if (!content || !content.trim()) return;

    try {
      const res = await fetch(`http://127.0.0.1:8000/api/comments/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ article: articleId, content }),
      });

      if (res.ok) {
        // очистити textarea тільки для цієї статті
        setNewComments((prev) => ({ ...prev, [articleId]: "" }));
        fetchComments(articleId);
      }
    } catch (err) {
      console.error("Помилка при додаванні коментаря:", err);
    }
  };

  // --- Видалити статтю ---
  const handleDelete = async (id) => {
    if (!window.confirm("Видалити статтю?")) return;

    try {
      const res = await fetch(`http://127.0.0.1:8000/api/articles/${id}/`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        alert("✅ Статтю видалено!");
        setArticles((prev) => prev.filter((a) => a.id !== id));
      } else {
        alert("❌ Помилка при видаленні статті");
      }
    } catch (err) {
      console.error("Помилка при видаленні статті:", err);
    }
  };

  return (
    <div className="articles-container">
      <h2 className="category-title">{category.toUpperCase()}</h2>
      {articles.length === 0 ? (
        <p>Немає статей у цій категорії.</p>
      ) : (
        <div className="articles-grid">
          {articles.map((a) => (
            <div className="article-card" key={a.id}>
              {a.image && <img src={a.image} alt={a.title} className="article-image" />}
              <h3>{a.title}</h3>
              <p>{a.excerpt || a.content.substring(0, 120) + "..."}</p>
              <small>
                {a.category} | {new Date(a.created_at).toLocaleDateString()}
              </small>

              {/* Кнопки редагування / видалення */}
              {isAdmin && (
                <div className="admin-controls">
                  <button onClick={() => navigate(`/edit-article/${a.id}`)}>✏️ Редагувати</button>
                  <button onClick={() => handleDelete(a.id)}>🗑️ Видалити</button>
                </div>
              )}

              {/* Кнопка коментарів */}
              <button
                className="comments-toggle-btn"
                onClick={() => handleToggleComments(a.id)}
              >
                💬 {expandedArticleId === a.id ? "Сховати коментарі" : "Показати коментарі"}
              </button>

              {/* Блок коментарів */}
              {expandedArticleId === a.id && (
                <div className="comments-section">
                  {comments[a.id] ? (
                    comments[a.id].length > 0 ? (
                      comments[a.id].map((c) => (
                        <div key={c.id} className="comment">
                          <strong>👤 {c.user_username || "Користувач"}</strong>
                          <p>{c.content}</p>
                        </div>
                      ))
                    ) : (
                      <p>Немає коментарів.</p>
                    )
                  ) : (
                    <p>Завантаження...</p>
                  )}

                  {/* Форма додавання коментаря */}
                  {token ? (
                    <div className="add-comment">
                      <textarea
                        placeholder="Напишіть коментар..."
                        value={newComments[a.id] || ""}
                        onChange={(e) =>
                          setNewComments((prev) => ({ ...prev, [a.id]: e.target.value }))
                        }
                      />
                      <button onClick={() => handleAddComment(a.id, newComments[a.id])}>
                        Надіслати
                      </button>
                    </div>
                  ) : (
                    <p>🔒 Увійдіть, щоб залишати коментарі</p>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default ArticlesPage;
